mapper.select:
select lal.*, a.lease_item_code as LEASE_ITEM_ID_N, a.lease_item_type, a.full_name, (SELECT meaning FROM sys_code_value_b_v v WHERE v.CODE = 'REVALUE_LEASE_ITEM_TYPE' AND v.code_value = a.lease_item_type) lease_item_type_n, (SELECT sum(hlid.net_asset_value) FROM hls_lease_item_detail hlid where hlid.lease_item_id = a.lease_item_id) as asset_value_total, (case when a.fair_value is null then (SELECT sum(hlid.net_asset_value) FROM hls_lease_item_detail hlid where hlid.lease_item_id = a.lease_item_id) else a.fair_value end) fair_value_recent, (select distinct(hbm.bp_name) from prj_project_bp ppb, prj_project pp , hls_bp_master hbm WHERE ppb.lease_item_id = a.lease_item_id and ppb.project_id = pp.project_id and ppb.bp_role_type IN ('MORTGAGOR', 'PLEDGOR') and hbm.bp_id = pp.tenant_id) bp_name, ( SELECT wm_concat( fa.file_name ) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name = 'lease_asset_ln' AND lal.asset_ln_id = fam.table_pk_value ) FILE_NAME, ( SELECT fa.attachment_id FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name = 'lease_asset_ln' AND lal.asset_ln_id = fam.table_pk_value ) ATTACHMENT_ID from lease_asset_ln lal,lease_asset_hd lah,hls_lease_item a where lal.ASSET_HD_ID = lah.ASSET_HD_ID and lal.LEASE_ITEM_ID = a.LEASE_ITEM_ID
and lal.ASSET_HD_ID = #{assetHdId}
order by lal.EVALUATION_DATE desc
